def build_prefix(values):
    prefix = [0]
    for value in values:
        prefix.append(prefix[-1] + value)
    return prefix

def range_sum(prefix, left, right):
    if not 0 <= left <= right < len(prefix):
        raise ValueError("invalid range")
    return prefix[right] - prefix[left]

values = [4, -1, 3, 2]
prefix = build_prefix(values)
print(prefix)
for left, right in [(0, 4), (1, 3), (2, 2)]:
    print(range_sum(prefix, left, right))
print(values)

def prefix_query(prefix, left, right):
    if not 0 <= left <= right < len(prefix):
        raise ValueError('invalid range')
    return prefix[right] - prefix[left]

print(prefix_query([0, 2, 7, 6], 1, 3))
print(prefix_query([0, 2, 7, 6], 3, 3))
print(prefix_query([0], 0, 0))
try:
    print(prefix_query([0, 2, 7, 6], 0, 4))
except ValueError:
    print('ValueError')

def batch_prefix_sums(values, queries):
    prefix = [0]
    for value in values:
        prefix.append(prefix[-1] + value)
    answers = []
    for left, right in queries:
        if not 0 <= left <= right <= len(values):
            raise ValueError('invalid range')
        answers.append(prefix[right] - prefix[left])
    return answers

print(batch_prefix_sums([2, -1, 5], [(0, 3), (1, 3), (1, 1)]))
print(batch_prefix_sums([], [(0, 0)]))
print(batch_prefix_sums([7], []))
try:
    print(batch_prefix_sums([7], [(0, 2)]))
except ValueError:
    print('ValueError')

def replace_and_prefix(values, index, new_value):
    if not 0 <= index < len(values):
        raise ValueError('invalid index')
    changed = list(values)
    changed[index] = new_value
    prefix = [0]
    for value in changed:
        prefix.append(prefix[-1] + value)
    return changed, prefix

print(replace_and_prefix([2, 5, 1], 1, 9))
print(replace_and_prefix([0], 0, -3))
try:
    print(replace_and_prefix([], 0, 1))
except ValueError:
    print('ValueError')
